import '@kerfjs/ui/layout.css';
import '@kerfjs/ui/webawesome.css';
import '@awesome.me/webawesome/dist/components/dialog/dialog.js';
import { DialogHeader } from '@kerfjs/ui/dialog-header';
import { EmptyState } from '@kerfjs/ui/empty-state';
import { delegate } from './events';
import './palette.css';

// Catalog checked: there is no CommandPalette export or equivalent complete command widget.
// A native search input plus grouped command buttons is an honest application composition.
type Command = { id: string; label: string; group: string; run(): void; disabled?: boolean };
type Dialog = HTMLElement & { open: boolean };
export function createCommandPalette(root: HTMLElement, paint: (html: ReturnType<typeof DialogHeader>) => void, commands: Command[], history: { read(): string[]; write(ids: string[]): void }) {
  let query = '';
  let recent = history.read().filter(id => commands.some(command => command.id === id));
  let open = false;
  let invoker: HTMLElement | null = null;
  const matches = () => commands.filter(command => command.label.toLocaleLowerCase().includes(query.trim().toLocaleLowerCase()));
  const groups = () => {
    const results = matches();
    const rows: { name: string; commands: Command[] }[] = [];
    const recentCommands = query.trim() ? [] : recent.map(id => results.find(command => command.id === id)).filter((item): item is Command => !!item);
    if (recentCommands.length) rows.push({ name: 'Recent commands', commands: recentCommands });
    const remaining = results.filter(command => !recentCommands.includes(command));
    for (const name of new Set(remaining.map(command => command.group))) rows.push({ name, commands: remaining.filter(command => command.group === name) });
    return rows;
  };
  const render = () => <section class="app-root kui-layout">
    <button class="app-button" type="button" data-action="palette-show">Commands</button>
    <wa-dialog class="command-dialog" label="Commands" without-header open={open} aria-labelledby="commands-title" aria-describedby="commands-summary">
      <DialogHeader title="Commands" titleId="commands-title" summary="Search commands. Use Tab or arrow keys to move through results, and Enter to run." summaryId="commands-summary" actions={<button class="app-button" type="button" data-action="palette-close">Close</button>} />
      <div class="kui-dialog-body kui-section-stack">
        <label for="command-query">Search commands</label><input id="command-query" type="search" value={query} autocomplete="off" />
        <p role="status" aria-live="polite">{matches().length} commands available</p>
        {groups().length ? groups().map((group, index) => <section aria-labelledby={'command-group-' + index}><h2 id={'command-group-' + index}>{group.name}</h2><ul>{group.commands.map(command => <li><button class="app-button" type="button" data-action="palette-run" data-command-id={command.id} disabled={command.disabled}>{command.label}</button></li>)}</ul></section>) : <EmptyState title="No matching commands" detail="Try another search or clear the query." action={<button class="app-button" type="button" data-action="palette-clear">Clear search</button>} />}
      </div>
    </wa-dialog>
  </section>;
  const dialog = () => root.querySelector<Dialog>('wa-dialog')!;
  const input = () => root.querySelector<HTMLInputElement>('#command-query')!;
  const buttons = () => Array.from(root.querySelectorAll<HTMLButtonElement>('[data-action="palette-run"]:not(:disabled)'));
  const offActions = delegate(root, 'click', '[data-action]', element => {
    switch (element.dataset.action) {
      case 'palette-show': invoker = element; element.focus(); open = true; dialog().open = true; break;
      case 'palette-close': dialog().open = false; break;
      case 'palette-clear': query = ''; paint(render()); input().focus(); break;
      case 'palette-run': {
        const command = commands.find(item => item.id === element.dataset.commandId && !item.disabled);
        if (!command) return;
        recent = [command.id, ...recent.filter(id => id !== command.id)].slice(0, 10);
        history.write(recent); dialog().open = false; command.run(); break;
      }
    }
  });
  const offInput = delegate(root, 'input', '#command-query', element => {
    const source = element as HTMLInputElement;
    query = source.value;
    const caret = source.selectionStart;
    paint(render());
    input().focus();
    if (caret !== null) input().setSelectionRange(caret, caret);
  });
  const offKeys = delegate(root, 'keydown', '#command-query,[data-action="palette-run"]', (element, event) => {
    const key = event as KeyboardEvent;
    if (key.isComposing) return;
    const results = buttons();
    const index = results.indexOf(element as HTMLButtonElement);
    if (element === input() && key.key === 'Enter') { key.preventDefault(); results[0]?.click(); return; }
    if (!['ArrowDown', 'ArrowUp', 'Home', 'End'].includes(key.key)) return;
    // Home/End in the search input keep ordinary text-caret behavior.
    if (element === input() && ['Home', 'End'].includes(key.key)) return;
    key.preventDefault();
    if (!results.length) return;
    const target = key.key === 'Home' ? 0 : key.key === 'End' ? results.length - 1 : key.key === 'ArrowDown' ? (index + 1) % results.length : index <= 0 ? results.length - 1 : index - 1;
    results[target]?.focus();
  });
  const shown = (event: Event) => { if (event.target === dialog()) input().focus(); };
  const hidden = (event: Event) => { if (event.target !== dialog()) return; open = false; if (invoker?.isConnected) invoker.focus(); };
  root.addEventListener('wa-after-show', shown);
  root.addEventListener('wa-after-hide', hidden);
  paint(render());
  return { render, dispose() { offActions(); offInput(); offKeys(); root.removeEventListener('wa-after-show', shown); root.removeEventListener('wa-after-hide', hidden); } };
}
// Modal trapping and Escape belong to wa-dialog. Native buttons provide Tab and Enter/Space.
// This is not an ARIA menu or combobox; no unsupported partial widget roles are added.

